<?php
namespace Modules\BankingMicrofinanceTreasury\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryVault;
class VaultController extends Controller{public function index(){return view('bankingmicrofinancetreasury::vaults.index',['vaults'=>TreasuryVault::latest()->paginate(25)]);}public function create(){return view('bankingmicrofinancetreasury::vaults.form',['vault'=>new TreasuryVault]);}public function store(Request $r){TreasuryVault::create($r->all()+['business_id'=>auth()->user()->business_id ?? null]);return redirect()->route('bkg.mfi.treasury.vaults.index')->with('status','Vault saved');}public function edit(TreasuryVault $vault){return view('bankingmicrofinancetreasury::vaults.form',compact('vault'));}public function update(Request $r,TreasuryVault $vault){$vault->update($r->all());return redirect()->route('bkg.mfi.treasury.vaults.index')->with('status','Vault updated');}public function destroy(TreasuryVault $vault){$vault->delete();return back()->with('status','Vault removed');}}
